WITH counts AS (SELECT 'supplier' AS table_name,count(*) AS row_count FROM supplytrace.supplier UNION ALL SELECT 'component' AS table_name,count(*) AS row_count FROM supplytrace.component UNION ALL SELECT 'component_batch' AS table_name,count(*) AS row_count FROM supplytrace.component_batch UNION ALL SELECT 'product_model' AS table_name,count(*) AS row_count FROM supplytrace.product_model UNION ALL SELECT 'manufacturing_batch' AS table_name,count(*) AS row_count FROM supplytrace.manufacturing_batch UNION ALL SELECT 'batch_component_usage' AS table_name,count(*) AS row_count FROM supplytrace.batch_component_usage UNION ALL SELECT 'warehouse' AS table_name,count(*) AS row_count FROM supplytrace.warehouse UNION ALL SELECT 'inventory' AS table_name,count(*) AS row_count FROM supplytrace.inventory UNION ALL SELECT 'retailer' AS table_name,count(*) AS row_count FROM supplytrace.retailer UNION ALL SELECT 'sales_order' AS table_name,count(*) AS row_count FROM supplytrace.sales_order UNION ALL SELECT 'order_line' AS table_name,count(*) AS row_count FROM supplytrace.order_line UNION ALL SELECT 'stock_allocation' AS table_name,count(*) AS row_count FROM supplytrace.stock_allocation UNION ALL SELECT 'shipment' AS table_name,count(*) AS row_count FROM supplytrace.shipment UNION ALL SELECT 'shipment_line' AS table_name,count(*) AS row_count FROM supplytrace.shipment_line UNION ALL SELECT 'product_configuration' AS table_name,count(*) AS row_count FROM supplytrace.product_configuration) SELECT * FROM counts UNION ALL SELECT 'TOTAL',sum(row_count) FROM counts;
